package local.lito381.server;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class AreaNpcProbe extends AreaMaterialProbe {
 static boolean active(ClassicWorldMonsterPopulation pop,int map,long id,int skill){return skill==161?pop.areaSilenceActive(map,id,System.nanoTime()):pop.windShackleActive(map,id,System.nanoTime());}
 static void exercise(ClientSession pc,ClientSession peer,GameHub hub,GameStateStore state,boolean world,int skill,int mode)throws Exception{
  CancellationMaterialProbe.setup(pc,peer,hub,true);CancellationMaterialProbe.probability(skill);set(pc,"learnedSkills",new HashSet<>(Set.of(skill)));set(pc,"elfAttribute",31);
  var npc=CancellationWorldNpcProbe.monster(pc,hub);var pop=(ClassicWorldMonsterPopulation)get(hub,"classicWorldMonsters");int map=(int)get(pc,"classicWorldMapId");Object actor=NativeCancellationNpcMaterialAction.actor(pop,npc.objectId());
  var row=spell(skill);int item=value(row,"itemConsumeId"),count=value(row,"itemConsumeCount"),expected=cost(pc,skill,row);if(mode!=1)NativeDeItemPublication.grant(pc,item,count+3);
  Runnable mutate=()->{try{if(mode==2||mode==5){pop.damage(map,npc.objectId(),Integer.MAX_VALUE);pop.removeCorpse(map,npc.objectId());need(pop.respawn(map,npc.objectId())!=null,"actual same-ID NPC respawn");}if(mode==3)set(hub,"classicWorldMonsters",ClassicWorldMonsterPopulation.retainedSourceSlice(8,0x5f000000L,0x5f0000ffL,List.of((ClassicWorldMonsterCatalog.SpawnDefinition)get(actor,"definition"))));}catch(Exception e){throw new RuntimeException(e);}};
  var fail=new AtomicReference<Throwable>();byte[] payload=packet(skill,npc.objectId());
  Runnable cast=()->{try{call(pc,skill==161?"useAreaSilenceSpell":"useWindShackleSpell",new Class[]{byte[].class,row.getClass(),int.class},payload,row,mode==7?100:1);}catch(Throwable e){fail.set(e);}};
  try(var self=new SourceActionPairProbe.Wire(pc,peer);var other=new SourceActionPairProbe.Wire(peer,pc)){
   boolean accepted=mode!=1&&!(skill==167&&(mode==2||mode==3));
   if(mode==2||mode==3){var lock=peer.nativePlayerActionLock();var worker=new Thread(cast);lock.lock();try{worker.start();long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(2);while(worker.isAlive()&&worker.getState()!=Thread.State.TIMED_WAITING&&System.nanoTime()<end)Thread.onSpinWait();need(worker.getState()==Thread.State.TIMED_WAITING,"NPC membership frozen before player locks");synchronized(hub){synchronized(pop){mutate.run();}}}finally{lock.unlock();worker.join(4000);}need(!worker.isAlive(),"NPC lifetime worker completed");}
   else if(mode>=4&&mode<=6){NativeSourcePlayerActionLock.run(pc,()->{cast.run();if(fail.get()!=null)return;need(active(pop,map,npc.objectId(),skill),"effect committed before deferred NPC publication");need(self.raw.size()==0&&other.raw.size()==0,"NPC output deferred");if(mode==4)NativePlayerCommit.selected(pc,pc.selectedCharacterName());if(mode==5)mutate.run();if(mode==6)NativePlayerCommit.selected(peer,peer.selectedCharacterName());});}
   else cast.run();
   if(fail.get()!=null)throw new AssertionError(fail.get());
   need((int)get(pc,"playerMp")==1000-(accepted?expected:0)&&pc.nativeDeInventory(0).countCatalog(item)==(mode==1?0:count+3-(accepted?count:0)),"NPC area single material/MP admission mode="+mode);
   need(active(pop,map,npc.objectId(),skill)==(accepted&&mode!=2&&mode!=3&&mode!=5&&mode!=7),"effect remains on captured NPC life only mode="+mode);
   var a=collect(self);var b=collect(other);String fx=HexFormat.of().formatHex(Protocol.effectObject(npc.objectId(),value(row,"effectGfx")));
   if(mode==1)need(a.equals(List.of(HexFormat.of().formatHex(Protocol.messageCode(299))))&&b.isEmpty(),"NPC missing material299");
   if(mode==0)need(a.contains(fx)&&b.contains(fx),"both viewers receive actual NPC effect");
   if(mode==2||mode==3||mode==5||mode==7)need(!a.contains(fx)&&!b.contains(fx),"no retired/failed NPC effect");
   if(mode==4)need(a.isEmpty()&&b.contains(fx),"NPC effect still published to peer after caster retirement");
   if(mode==6)need(a.contains(fx)&&b.isEmpty(),"retired viewer receives nothing");
   need(self.locked+other.locked==0&&NativeAreaMaterialAction.current.get()==null&&NativePlayerVitalCompletions.pending(NativePlayerLifetime.of(pc))==0,"NPC scopes drained unlocked");
  }cases++;
 }
 public static void main(String[]args)throws Exception{before=args[4].equals("before");var jar=Path.of(args[3]).toRealPath();for(var type:List.of(ClientSession.class,RuntimeInventory.class,NativeCastMaterial.class,NativeDeItemTransaction.class))need(Path.of(type.getProtectionDomain().getCodeSource().getLocation().toURI()).toRealPath().equals(jar),"actual native handlers and material authority from requested JAR");var base=ServerConfig.load(Path.of(args[0]),"standard");ResourceDatabase.load(base);var templates=new NativeDeItemTemplatesResources.Owner().reload(base);var definitions=new NativeDeItemDefinitionsResources.Owner().reload(base);var root=Path.of(args[1]);Throwable primary=null;
  try{for(boolean flag:new boolean[]{false,true})for(boolean world:new boolean[]{true})for(boolean app:new boolean[]{false,true})for(int skill:SKILLS)for(int mode=0;mode<8;mode++){var r=root.resolve(flag+"-"+world+"-"+app+"-"+skill+"-"+mode);Files.createDirectories(r);var cfg=copy(base,Map.of("battleNaturalHpRegenEnabled",false,"battleNaturalMpRegenEnabled",false,"statePersistenceEnabled",flag,"stateFile",r.resolve("must-not-write.properties")));var state=new GameStateStore(r.resolve("must-not-write.properties"),false,true);var accounts=new MemoryAccountRepository("fixture","fixture","",0,1,40,52);
   try(var capture=new CaptureLog(r.resolve("capture"));var hub=new GameHub(cfg,state,accounts);var f=new SourceLoginRegression.Fixture(cfg,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME);var p=new SourceLoginRegression.Fixture(cfg,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME);var m=new SourceLoginRegression.Fixture(cfg,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME);var o=new SourceLoginRegression.Fixture(cfg,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME)){var clock=(ScheduledExecutorService)get(hub,"battleClock");clock.shutdownNow();need(clock.awaitTermination(2,TimeUnit.SECONDS),"unrelated clock stopped");var fixtures=List.of(f,p,m,o);init(fixtures,cfg);FlowRegression.setup(hub,f.session,p.session,m.session,o.session);if(world)world(fixtures,hub);if(app)NativeDeItemApplication.install(hub,templates,definitions);exercise(p.session,m.session,hub,state,world,skill,mode);}need(!Files.exists(r.resolve("must-not-write.properties")),"both flags remain memory-only");
  }}catch(Throwable e){primary=e;throw e;}finally{try{NativePlayerCommit.closeFixture();}catch(Throwable e){if(primary!=null)primary.addSuppressed(e);else throw e;}}need(NativePlayerLifetime.allIdle(),"native lifetimes idle");var output=Path.of(args[2]);Files.writeString(output.resolveSibling("self-material-wire.txt"),String.join("\n",wires)+"\n");Files.writeString(output.resolveSibling("self-material-goldens.txt"),String.join("\n",goldens)+"\n");Files.writeString(output.resolveSibling("self-material-notes.txt"),String.join("\n",notes)+"\n");String result="{\"cases\":"+cases+",\"checks\":"+ownChecks+",\"self_skills\":2,\"material_skills\":2,\"Source_window_bypasses\":"+gaps+",\"actual_frames\":"+frames+",\"locked_write_calls\":"+lockedWrites+",\"production_PC_overlays\":0,\"full_goal_achieved\":false}";Files.writeString(output,result+"\n");System.out.println(result);}
}
